@@ -345,1 +342,1 @@
-  const bool rc = can_mprotect_archive_space && os::protect_memory((char*)addr, size, os::MEM_PROT_NONE, false);
+  const bool rc = os::protect_memory((char*)addr, size, os::MEM_PROT_NONE, false);
